// ─────────────────────────────────────────────────────────────
//  src/services/api.js
//  All calls to the NutriBite backend (Phase 2)
//  Falls back to Open Food Facts directly if backend is offline
// ─────────────────────────────────────────────────────────────

const BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

// ── Token helpers ─────────────────────────────────────
export const getToken  = ()       => localStorage.getItem('nb_token');
export const setToken  = (token)  => localStorage.setItem('nb_token', token);
export const clearToken = ()      => localStorage.removeItem('nb_token');

// ── Base fetch wrapper ────────────────────────────────
async function request(endpoint, options = {}) {
  const token = getToken();
  const headers = {
    'Content-Type': 'application/json',
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
    ...options.headers,
  };

  const res = await fetch(`${BASE}${endpoint}`, { ...options, headers });
  const data = await res.json();

  if (!res.ok) {
    throw new Error(data.message || `Request failed: ${res.status}`);
  }
  return data;
}

// ════════════════════════════════════════════════════════
//  AUTH
// ════════════════════════════════════════════════════════

export async function apiRegister({ name, email, password, dietType, preferences }) {
  const data = await request('/auth/register', {
    method: 'POST',
    body: JSON.stringify({ name, email, password, dietType, preferences }),
  });
  if (data.token) setToken(data.token);
  return data;
}

export async function apiLogin({ email, password }) {
  const data = await request('/auth/login', {
    method: 'POST',
    body: JSON.stringify({ email, password }),
  });
  if (data.token) setToken(data.token);
  return data;
}

export async function apiGetMe() {
  return request('/auth/me');
}

export async function apiUpdatePassword({ currentPassword, newPassword }) {
  return request('/auth/password', {
    method: 'PUT',
    body: JSON.stringify({ currentPassword, newPassword }),
  });
}

export function apiLogout() {
  clearToken();
}

// ════════════════════════════════════════════════════════
//  USER — PREFERENCES
// ════════════════════════════════════════════════════════

export async function apiGetPreferences() {
  return request('/user/preferences');
}

export async function apiUpdatePreferences(preferences) {
  return request('/user/preferences', {
    method: 'PUT',
    body: JSON.stringify(preferences),
  });
}

// ════════════════════════════════════════════════════════
//  USER — FAVORITES
// ════════════════════════════════════════════════════════

export async function apiGetFavorites() {
  return request('/user/favorites');
}

export async function apiAddFavoriteFood(food) {
  return request('/user/favorites/food', {
    method: 'POST',
    body: JSON.stringify({
      foodId:    food.id,
      name:      food.name,
      image:     food.image,
      calories:  food.calories,
      protein:   food.protein,
      carbs:     food.carbs,
      fat:       food.fat,
      fiber:     food.fiber,
      grade:     food.grade,
      labels:    food.labels,
      allergens: food.allergens,
    }),
  });
}

export async function apiRemoveFavoriteFood(foodId) {
  return request(`/user/favorites/food/${foodId}`, { method: 'DELETE' });
}

// ════════════════════════════════════════════════════════
//  USER — MEDICAL REPORTS
// ════════════════════════════════════════════════════════

export async function apiUploadMedicalReport(file, notes = '') {
  const token = getToken();
  const formData = new FormData();
  formData.append('report', file);
  formData.append('notes', notes);

  const res = await fetch(`${BASE}/user/medical`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body: formData,
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.message || 'Upload failed');
  return data;
}

export async function apiGetMedicalReports() {
  return request('/user/medical');
}

export async function apiDeleteMedicalReport(reportId) {
  return request(`/user/medical/${reportId}`, { method: 'DELETE' });
}

// ════════════════════════════════════════════════════════
//  USER — SEARCH HISTORY
// ════════════════════════════════════════════════════════

export async function apiGetSearchHistory() {
  return request('/user/search-history');
}

export async function apiClearSearchHistory() {
  return request('/user/search-history', { method: 'DELETE' });
}

// ════════════════════════════════════════════════════════
//  FOOD
// ════════════════════════════════════════════════════════

export async function apiGetRecommendations() {
  return request('/food/recommendations');
}

export async function apiSearchFoods(query, filter = '') {
  const params = new URLSearchParams({ q: query, ...(filter ? { filter } : {}) });
  return request(`/food/search?${params}`);
}

export async function apiGetFoodByBarcode(barcode) {
  return request(`/food/${barcode}`);
}

export async function apiGetDeliveryLink(name) {
  const params = new URLSearchParams({ name });
  return request(`/food/delivery-link?${params}`);
}
